size(120);
pair A,B,C,D,E,F,G,H,I,J,K,L;
A=(0,0);
B=(4,0);
C=(4,3);
D=(0,3);
E=(2,1.5);
F=(1.5,1.5);
G=(0,1.5);
H=(2,0);
I=(3,3);
J=(3,0);
K=(2.5,2.5);
L=(1.5,0);
draw(A--B--C--cycle);
draw(D--E--F--cycle);
